## Complex Widget (Folder Structure)

For widgets with multiple components:

```
resources/
└── product-search/
    ├── widget.tsx          # Entry point (required name)
    ├── components/
    │   ├── ProductCard.tsx
    │   └── FilterBar.tsx
    ├── hooks/
    │   └── useFilter.ts
    ├── types.ts
    └── constants.ts
```

**Entry point (`widget.tsx`):**

```tsx
import { McpUseProvider, useWidget, type WidgetMetadata } from "mcp-use/react";
import { z } from "zod";
import { ProductCard } from "./components/ProductCard";
import { FilterBar } from "./components/FilterBar";

export const widgetMetadata: WidgetMetadata = {
  description: "Display product search results with filtering",
  props: z.object({
    products: z.array(
      z.object({
        id: z.string(),
        name: z.string(),
        price: z.number(),
        image: z.string(),
      }),
    ),
    query: z.string(),
  }),
};

const ProductSearch: React.FC = () => {
  const { props, isPending, state, setState } = useWidget();

  if (isPending) {
    return (
      <McpUseProvider autoSize>
        <div>Loading...</div>
      </McpUseProvider>
    );
  }

  return (
    <McpUseProvider autoSize>
      <div>
        <h1>Search: {props.query}</h1>
        <FilterBar onFilter={(filters) => setState({ filters })} />
        <div className="grid grid-cols-3 gap-4">
          {props.products.map((p) => (
            <ProductCard key={p.id} product={p} />
          ))}
        </div>
      </div>
    </McpUseProvider>
  );
};

export default ProductSearch;
```

## Data Fetching Widget

Widget that refreshes data via tool calls:

```tsx
import { McpUseProvider, useWidget, type WidgetMetadata } from "mcp-use/react";
import { z } from "zod";

export const widgetMetadata: WidgetMetadata = {
  description: "Display data with refresh capability",
  props: z.object({
    id: z.string(),
    title: z.string(),
    data: z.array(z.any()),
  }),
};

const DataWidget: React.FC = () => {
  const { props, isPending, callTool } = useWidget();

  if (isPending) return <div>Loading...</div>;

  const refresh = async () => {
    try {
      await callTool("fetch-data", { id: props.id });
    } catch (error) {
      console.error("Refresh failed:", error);
    }
  };

  return (
    <McpUseProvider autoSize>
      <div>
        <h1>{props.title}</h1>
        <button onClick={refresh}>Refresh</button>
        <ul>
          {props.data.map((item, i) => (
            <li key={i}>{JSON.stringify(item)}</li>
          ))}
        </ul>
      </div>
    </McpUseProvider>
  );
};

export default DataWidget;
```

## Stateful Widget

Widget with persistent state across interactions:

```tsx
import { McpUseProvider, useWidget, type WidgetMetadata } from "mcp-use/react";
import { z } from "zod";

export const widgetMetadata: WidgetMetadata = {
  description: "Counter with persistent state",
  props: z.object({
    initialValue: z.number().optional(),
  }),
};

const CounterWidget: React.FC = () => {
  const { props, isPending, state, setState } = useWidget();

  if (isPending) return <div>Loading...</div>;

  const count = state?.count ?? props.initialValue ?? 0;

  const increment = async () => {
    await setState({ count: count + 1 });
  };

  const decrement = async () => {
    await setState({ count: count - 1 });
  };

  return (
    <McpUseProvider autoSize>
      <div className="flex items-center gap-4">
        <button onClick={decrement}>-</button>
        <span className="text-2xl">{count}</span>
        <button onClick={increment}>+</button>
      </div>
    </McpUseProvider>
  );
};

export default CounterWidget;
```

## Themed Widget

Widget that respects light/dark theme:

```tsx
import { McpUseProvider, useWidget, type WidgetMetadata } from "mcp-use/react";
import { z } from "zod";

export const widgetMetadata: WidgetMetadata = {
  description: "Theme-aware content display",
  props: z.object({
    title: z.string(),
    content: z.string(),
  }),
};

const ThemedWidget: React.FC = () => {
  const { props, isPending, theme } = useWidget();

  if (isPending) return <div>Loading...</div>;

  const isDark = theme === "dark";

  return (
    <McpUseProvider autoSize>
      <div
        className={`p-4 rounded-lg ${
          isDark ? "bg-gray-900 text-white" : "bg-white text-gray-900"
        }`}
      >
        <h1
          className={`text-xl font-bold ${isDark ? "text-blue-400" : "text-blue-600"}`}
        >
          {props.title}
        </h1>
        <p className={isDark ? "text-gray-300" : "text-gray-700"}>
          {props.content}
        </p>
      </div>
    </McpUseProvider>
  );
};

export default ThemedWidget;
```

## Widget with Tool Calls

Widget that calls other MCP tools:

```tsx
import { McpUseProvider, useWidget, type WidgetMetadata } from "mcp-use/react";
import { z } from "zod";
import { useState } from "react";

export const widgetMetadata: WidgetMetadata = {
  description: "City weather lookup with search",
  props: z.object({
    defaultCity: z.string().optional(),
  }),
};

const WeatherSearch: React.FC = () => {
  const { props, isPending, callTool, state, setState } = useWidget();
  const [loading, setLoading] = useState(false);
  const [city, setCity] = useState(props.defaultCity || "");

  if (isPending) return <div>Loading...</div>;

  const searchWeather = async () => {
    if (!city.trim()) return;
    setLoading(true);
    try {
      const result = await callTool("get-weather", { city });
      await setState({ lastResult: result.content, lastCity: city });
    } catch (error) {
      console.error("Search failed:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <McpUseProvider autoSize>
      <div className="p-4">
        <div className="flex gap-2 mb-4">
          <input
            type="text"
            value={city}
            onChange={(e) => setCity(e.target.value)}
            placeholder="Enter city name"
            className="border rounded px-2 py-1"
          />
          <button onClick={searchWeather} disabled={loading}>
            {loading ? "Searching..." : "Search"}
          </button>
        </div>
        {state?.lastResult && (
          <div>
            <h3>Weather in {state.lastCity}:</h3>
            <pre>{JSON.stringify(state.lastResult, null, 2)}</pre>
          </div>
        )}
      </div>
    </McpUseProvider>
  );
};

export default WeatherSearch;
```

# Custom Authentication

Setting up OAuth with any identity provider (GitHub, Okta, Azure AD, Google, etc.).

---

## Quick Start

```typescript
import { MCPServer, oauthCustomProvider, object } from "mcp-use/server";
import { createRemoteJWKSet, jwtVerify } from "jose";

const JWKS = createRemoteJWKSet(
  new URL("https://login.example.com/.well-known/jwks.json"),
);

const server = new MCPServer({
  name: "my-server",
  version: "1.0.0",
  oauth: oauthCustomProvider({
    issuer: "https://login.example.com",
    jwksUrl: "https://login.example.com/.well-known/jwks.json",
    authEndpoint: "https://login.example.com/oauth2/authorize",
    tokenEndpoint: "https://login.example.com/oauth2/token",
    verifyToken: async (token) => {
      const result = await jwtVerify(token, JWKS, {
        issuer: "https://login.example.com",
      });
      return result;
    },
  }),
});

server.tool(
  { name: "whoami", description: "Get authenticated user info" },
  async (_args, ctx) =>
    object({
      userId: ctx.auth.user.userId,
      email: ctx.auth.user.email,
    }),
);

server.listen();
```

---

## Configuration Options

```typescript
oauth: oauthCustomProvider({
  issuer: "https://login.example.com",              // required
  jwksUrl: "https://login.example.com/.well-known/jwks.json",  // required
  authEndpoint: "https://login.example.com/authorize",          // required
  tokenEndpoint: "https://login.example.com/token",             // required
  verifyToken: async (token) => { ... },             // required
  getUserInfo: (payload) => ({ ... }),                // optional
  scopesSupported: ["openid", "profile", "email"],   // optional
  grantTypesSupported: ["authorization_code", "refresh_token"], // optional
})
```

| Option                | Type                                      | Required | Description                                           |
| --------------------- | ----------------------------------------- | -------- | ----------------------------------------------------- |
| `issuer`              | `string`                                  | Yes      | OAuth issuer URL                                      |
| `jwksUrl`             | `string`                                  | Yes      | JWKS endpoint for key discovery                       |
| `authEndpoint`        | `string`                                  | Yes      | Authorization endpoint                                |
| `tokenEndpoint`       | `string`                                  | Yes      | Token endpoint                                        |
| `verifyToken`         | `(token: string) => Promise<{ payload }>` | Yes      | Custom JWT verification function                      |
| `getUserInfo`         | `(payload) => UserInfo`                   | No       | Custom user info extraction                           |
| `scopesSupported`     | `string[]`                                | No       | Defaults to `["openid", "profile", "email"]`          |
| `grantTypesSupported` | `string[]`                                | No       | Defaults to `["authorization_code", "refresh_token"]` |

---

## Token Verification

You must provide a `verifyToken` function that validates the JWT and returns `{ payload }`:

```typescript
import { createRemoteJWKSet, jwtVerify } from "jose";

const JWKS = createRemoteJWKSet(
  new URL("https://login.example.com/.well-known/jwks.json"),
);

verifyToken: async (token) => {
  const result = await jwtVerify(token, JWKS, {
    issuer: "https://login.example.com",
    audience: "my-api", // if your provider requires audience validation
  });
  return result;
};
```

The `jose` library is already a dependency of mcp-use, so no additional install is needed.

---

## Custom User Info Extraction

Without `getUserInfo`, the provider extracts standard OIDC claims automatically:

| Field         | Extracted From                     |
| ------------- | ---------------------------------- |
| `userId`      | `sub`, `user_id`, or `id`          |
| `email`       | `email`                            |
| `name`        | `name`                             |
| `username`    | `username` or `preferred_username` |
| `nickname`    | `nickname`                         |
| `picture`     | `picture` or `avatar_url`          |
| `roles`       | `roles` (if array)                 |
| `permissions` | `permissions` (if array)           |
| `scopes`      | Parsed from `scope` string         |

Override this if your provider uses non-standard claim names:

```typescript
getUserInfo: (payload) => ({
  userId: payload.user_id as string,
  email: payload.mail as string,
  name: payload.display_name as string,
  roles: (payload.groups as string[]) || [],
});
```

---

## Provider Examples

### GitHub (via GitHub Apps)

```typescript
oauth: oauthCustomProvider({
  issuer: "https://github.com",
  jwksUrl: "https://token.actions.githubusercontent.com/.well-known/jwks",
  authEndpoint: "https://github.com/login/oauth/authorize",
  tokenEndpoint: "https://github.com/login/oauth/access_token",
  verifyToken: async (token) => {
    // GitHub tokens may need introspection rather than local JWT verification
    const res = await fetch("https://api.github.com/user", {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) throw new Error("Invalid token");
    const user = await res.json();
    return { payload: user };
  },
  getUserInfo: (payload) => ({
    userId: String(payload.id),
    email: payload.email as string,
    name: payload.name as string,
    username: payload.login as string,
    picture: payload.avatar_url as string,
  }),
});
```

### Okta

```typescript
import { createRemoteJWKSet, jwtVerify } from "jose";

const OKTA_DOMAIN = process.env.OKTA_DOMAIN; // e.g., "dev-123456.okta.com"
const JWKS = createRemoteJWKSet(
  new URL(`https://${OKTA_DOMAIN}/oauth2/default/v1/keys`),
);

oauth: oauthCustomProvider({
  issuer: `https://${OKTA_DOMAIN}/oauth2/default`,
  jwksUrl: `https://${OKTA_DOMAIN}/oauth2/default/v1/keys`,
  authEndpoint: `https://${OKTA_DOMAIN}/oauth2/default/v1/authorize`,
  tokenEndpoint: `https://${OKTA_DOMAIN}/oauth2/default/v1/token`,
  verifyToken: async (token) =>
    jwtVerify(token, JWKS, {
      issuer: `https://${OKTA_DOMAIN}/oauth2/default`,
    }),
});
```

### Azure AD

```typescript
import { createRemoteJWKSet, jwtVerify } from "jose";

const TENANT_ID = process.env.AZURE_TENANT_ID;
const JWKS = createRemoteJWKSet(
  new URL(`https://login.microsoftonline.com/${TENANT_ID}/discovery/v2.0/keys`),
