import { useEffect, type RefObject } from "react";

export function useCarouselAnimation(
  carouselContainerRef: RefObject<HTMLDivElement | null>,
  scrollContainerRef: RefObject<HTMLDivElement | null>,
): void {
  useEffect(() => {
    let lastPointerX = 0;
    let lastPointerY = 0;

    const updateItems = () => {
      const container = carouselContainerRef.current;
      if (!container) return;

      const articles =
        container.querySelectorAll<HTMLElement>(".carousel-item");

      articles.forEach((article) => {
        const rect = article.getBoundingClientRect();
        const centerX = rect.left + rect.width / 2;
        const centerY = rect.top + rect.height / 2;
        const relativeX = lastPointerX - centerX;
        const relativeY = lastPointerY - centerY;
        const x = relativeX / (rect.width / 2);
        const y = relativeY / (rect.height / 2);

        // Calculate distance from cursor to center of item
        const distance = Math.sqrt(
          relativeX * relativeX + relativeY * relativeY,
        );
        // Use a larger max distance to make the effect work across gaps
        const maxDistance = Math.max(rect.width, rect.height) * 2;
        const normalizedDistance = Math.min(distance / maxDistance, 1);

        // Closer items get higher opacity and scale
        // Use exponential falloff for smoother transition
        const proximity = Math.pow(1 - normalizedDistance, 2);
        const opacity = 0.1 + proximity * 0.3; // Range from 0.1 to 0.4
        const scale = 2.0 + proximity * 2.0; // Range from 2.0 to 4.0

        article.style.setProperty("--pointer-x", x.toFixed(3));
        article.style.setProperty("--pointer-y", y.toFixed(3));
        article.style.setProperty("--icon-opacity", opacity.toFixed(3));
        article.style.setProperty("--icon-scale", scale.toFixed(2));
      });
    };

    const handlePointerMove = (event: { clientX: number; clientY: number }) => {
      lastPointerX = event.clientX;
      lastPointerY = event.clientY;
      updateItems();
    };

    const handleScroll = () => {
      updateItems();
    };

    document.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("scroll", handleScroll, true);

    const scrollContainer = scrollContainerRef.current;
    if (scrollContainer) {
      scrollContainer.addEventListener("scroll", handleScroll);
    }

    // Initial update
    updateItems();

    return () => {
      document.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("scroll", handleScroll, true);
      const container = scrollContainerRef.current;
      if (container) {
        container.removeEventListener("scroll", handleScroll);
      }
    };
  }, [carouselContainerRef, scrollContainerRef]);
}

import { z } from "zod";

export const propSchema = z.object({
  query: z.string().describe("The search query"),
  results: z.array(
    z.object({
      fruit: z.string().describe("Fruit name"),
      color: z.string().describe("Tailwind background color class"),
    }),
  ),
});

export type ProductSearchResultProps = z.infer<typeof propSchema>;

export type AccordionItemProps = {
  question: string;
  answer: string;
  isOpen: boolean;
  onToggle: () => void;
};

import { AppsSDKUIProvider } from "@openai/apps-sdk-ui/components/AppsSDKUIProvider";
import {
  Image,
  McpUseProvider,
  useCallTool,
  useWidget,
  type WidgetMetadata,
} from "mcp-use/react";
import React, { useCallback } from "react";
import { Link } from "react-router";
import "../styles.css";
import { Carousel } from "./components/Carousel";
import { CarouselSkeleton } from "./components/CarouselSkeleton";
import { Accordion } from "./components/Accordion";
import type { ProductSearchResultProps } from "./types";
import { propSchema } from "./types";
import { Button } from "@openai/apps-sdk-ui/components/Button";
import {
  Expand,
  HeartFilled,
  HeartXs,
  PictureInPicture,
} from "@openai/apps-sdk-ui/components/Icon";
export const widgetMetadata: WidgetMetadata = {
  description:
    "Display product search results with filtering, state management, and tool interactions",
  props: propSchema,
  exposeAsTool: false,
  metadata: {
    prefersBorder: false,
    invoking: "Loading product search results...",
    invoked: "Product search results loaded",
    csp: {
      // Widget-specific
      resourceDomains: ["https://cdn.openai.com"],
    },
  },
};
type FavoritesState = { favorites: string[] };

const ProductSearchResult: React.FC = () => {
  const {
    props,
    isPending,
    displayMode,
    requestDisplayMode,
    sendFollowUpMessage,
    locale,
    state,
    setState,
  } = useWidget<ProductSearchResultProps, FavoritesState>();

  const {
    callTool: getFruitDetails,
    data: fruitDetails,
    isPending: isLoadingDetails,
  } = useCallTool("get-fruit-details");

  const selectedFruit = fruitDetails?.structuredContent as
    | { fruit: string; facts?: string[] }
    | undefined;
  const favorites = state?.favorites ?? [];

  const toggleFavorite = useCallback(
    (fruit: string) => {
      const current = state?.favorites ?? [];
      const next = current.includes(fruit)
        ? current.filter((f: string) => f !== fruit)
        : [...current, fruit];
      setState({ favorites: next });
    },
    [state, setState],
  );

  const accordionItems = [
    {
      question: "Demo of the autosize feature",
      answer:
        "This is a demo of the autosize feature. The widget will automatically resize to fit the content, as supported by the mcp-apps specification",
    },
  ];

  if (isPending) {
    return (
      <McpUseProvider>
        <div className="relative bg-surface-elevated border border-default rounded-3xl">
          <div className="p-8 pb-4">
            <h5 className="text-secondary mb-1">MCP-Apps Template</h5>
            <h2 className="heading-xl mb-3">Lovely Little Fruit Shop</h2>
            <div className="h-5 w-48 rounded-md bg-default/10 animate-pulse" />
          </div>
          <CarouselSkeleton />
        </div>
      </McpUseProvider>
    );
  }

  const { query, results } = props;
  const isFullscreen = displayMode === "fullscreen";
  const isPip = displayMode === "pip";
  const lang = locale?.split("-")[0] ?? "en";

  return (
    <McpUseProvider>
      <AppsSDKUIProvider linkComponent={Link}>
        <div className="relative bg-surface-elevated border border-default rounded-3xl">
          {/* Toolbar — top-right badges and controls */}
          <div className="absolute top-4 right-4 z-10 flex items-center gap-2">
            {/* Locale badge */}
            <span className="px-2.5 py-1 text-xs font-medium rounded-full text-secondary uppercase tracking-wide">
              {lang}
            </span>

            {/* Favorites count */}
            {favorites.length > 0 && (
              <Button
                color="secondary"
                pill
                size="lg"
                uniform
                variant="ghost"
                className="text-danger/80"
              >
                <HeartFilled />
                {favorites.length}
              </Button>
            )}

            {/* Display mode buttons */}
            {!isFullscreen && !isPip && (
              <>
                <Button
                  color="secondary"
                  pill
                  size="lg"
                  uniform
                  variant="outline"
                  onClick={() => requestDisplayMode("pip")}
                  title="Picture-in-picture"
                >
                  <PictureInPicture />
                </Button>
                <Button
                  color="secondary"
                  pill
                  size="lg"
                  uniform
                  variant="outline"
                  onClick={() => requestDisplayMode("fullscreen")}
                  title="Fullscreen"
                >
                  <Expand />
                </Button>
              </>
            )}

            {(isFullscreen || isPip) && (
              <Button
                color="secondary"
                pill
                size="lg"
                uniform
                variant="outline"
                onClick={() => requestDisplayMode("inline")}
                title="Exit"
              >
                <svg
                  width="14"
                  height="14"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <line x1="18" y1="6" x2="6" y2="18" />
                  <line x1="6" y1="6" x2="18" y2="18" />
                </svg>
              </Button>
            )}
          </div>

          {/* Header */}
          <div className="p-8 pb-4">
            <h5 className="text-secondary mb-1">MCP-Apps Template</h5>
            <h2 className="heading-xl mb-1">Lovely Little Fruit Shop</h2>
            <p className="text-md text-secondary">
              {query
                ? `Showing results for "${query}"`
                : "Tap a fruit to see details"}
            </p>
          </div>

          {/* Carousel */}
          <Carousel
            results={results}
            favorites={favorites}
            onSelectFruit={(fruit: string) =>
              getFruitDetails({ fruit } as never)
            }
            onToggleFavorite={toggleFavorite}
          />

          {/* Detail view */}
          {selectedFruit && (
            <div className="mx-8 my-6 rounded-2xl border border-default bg-surface p-5 flex items-center gap-6">
              <div
                className={`rounded-xl p-4 shrink-0 ${
                  results.find(
                    (r: { fruit: string }) => r.fruit === selectedFruit.fruit,
                  )?.color ?? ""
                }`}
              >
                <Image
                  src={`/fruits/${selectedFruit.fruit}.png`}
                  alt={selectedFruit.fruit}
                  className="w-24 h-24 object-contain"
                />
              </div>
              <div className="flex-1">
                {isLoadingDetails ? (
                  <div className="animate-pulse h-4 w-32 bg-surface-elevated rounded" />
                ) : (
                  <>
                    <div className="flex items-center gap-2 mb-2">
                      <h3 className="font-semibold text-lg capitalize">
                        {selectedFruit.fruit}
                      </h3>
                      <Button
                        color="secondary"
                        pill
                        size="md"
                        uniform
                        variant="ghost"
                        onClick={() => toggleFavorite(selectedFruit.fruit)}
                        title={
                          favorites.includes(selectedFruit.fruit)
                            ? "Remove from favorites"
                            : "Add to favorites"
                        }
                        className={
                          favorites.includes(selectedFruit.fruit)
                            ? "text-danger/80"
                            : "text-secondary"
                        }
                      >
                        {favorites.includes(selectedFruit.fruit) ? (
                          <HeartFilled />
                        ) : (
                          <HeartXs />
                        )}
                      </Button>
                    </div>
                    <ul className="space-y-1">
                      {(selectedFruit.facts ?? []).map((fact: string) => (
                        <li
                          key={fact}
                          className="text-sm text-secondary flex items-start gap-2"
                        >
                          <span className="text-info mt-0.5">•</span>
                          {fact}
                        </li>
                      ))}
                    </ul>
                    {/* Follow-up message demo — sends a message to the LLM from the widget */}
                    <button
                      onClick={() =>
                        sendFollowUpMessage(
                          `Tell me more interesting facts about ${selectedFruit.fruit}`,
                        )
                      }
                      className="mt-3 px-3 py-1.5 text-xs font-medium rounded-lg bg-info/10 text-info hover:bg-info/20 transition-colors cursor-pointer"
                    >
                      Ask the AI for more about {selectedFruit.fruit}
                    </button>
                  </>
                )}
              </div>
            </div>
          )}

          <Accordion items={accordionItems} />
        </div>
      </AppsSDKUIProvider>
    </McpUseProvider>
  );
};

export default ProductSearchResult;

@import "tailwindcss";
@import "@openai/apps-sdk-ui/css";

/* Configure Tailwind v4 to scan for classes */
@source "../node_modules/@openai/apps-sdk-ui";
@source "./**/*.{ts,tsx,js,jsx,html}";

@theme {
  /* Enable class-based dark mode */
  --color-scheme: light dark;
}

@variant dark (&:where(.dark, .dark *));

/* Custom styles */
body {
  margin: 0;
  font-family:
    -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", "Oxygen", "Ubuntu",
    "Cantarell", "Fira Sans", "Droid Sans", "Helvetica Neue", sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  @apply text-default;
}

p {
  @apply text-secondary;
}

a {
  @apply text-info;
}

/* Carousel scroll container with padding for blur effect */
.carousel-scroll-container {
  padding-bottom: 2rem;
}

/* Hover effect styles for carousel items */
.carousel-item {
  position: relative;
  container-type: size;
  cursor: pointer;
  transition-property: translate, scale;
  transition-duration: 0.12s;
  transition-timing-function: cubic-bezier(0.645, 0.045, 0.355, 1);
  -webkit-tap-highlight-color: transparent;
  overflow: hidden;
  border-radius: 12px;
}

.carousel-item:active {
  translate: 0 1px;
  scale: 0.99;
}

.carousel-item-content {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.carousel-item-bg {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  transform: translateZ(0);
  filter: blur(28px) saturate(5) brightness(1.3);
  translate: calc(var(--pointer-x, -10) * 50cqi)
    calc(var(--pointer-y, -10) * 50cqh);
  scale: var(--icon-scale, 3.4);
  opacity: var(--icon-opacity, 0.25);
  will-change: transform, filter, opacity;
  pointer-events: none;
  z-index: 1;
  transition:
    opacity 0.26s ease-out,
    scale 0.26s ease-out;
  border-radius: inherit;
}

.carousel-item-bg img {
  width: 100px;
  -webkit-user-select: none;
  user-select: none;
  -webkit-user-drag: none;
}

.carousel-item::after {
  content: "";
  position: absolute;
  pointer-events: none;
  inset: 0px;
  border-radius: inherit;
  border: 3px solid transparent;
  backdrop-filter: blur(0px) saturate(4.2) brightness(2.5) contrast(2.5);
  -webkit-backdrop-filter: blur(0px) saturate(4.2) brightness(2.5) contrast(2.5);
  mask:
    linear-gradient(#fff 0 100%) border-box,
    linear-gradient(#fff 0 100%) padding-box;
  mask-composite: exclude;
  z-index: 3;
  transform: translateZ(0);
}

import { MCPServer, object, text, widget } from "mcp-use/server";
import { z } from "zod";

// Fruit catalogue — shared between search-tools and get-fruit-details
const fruits = [
  { fruit: "mango", color: "bg-[#FBF1E1] dark:bg-[#FBF1E1]/10" },
  { fruit: "pineapple", color: "bg-[#f8f0d9] dark:bg-[#f8f0d9]/10" },
  { fruit: "cherries", color: "bg-[#E2EDDC] dark:bg-[#E2EDDC]/10" },
  { fruit: "coconut", color: "bg-[#fbedd3] dark:bg-[#fbedd3]/10" },
  { fruit: "apricot", color: "bg-[#fee6ca] dark:bg-[#fee6ca]/10" },
  { fruit: "blueberry", color: "bg-[#e0e6e6] dark:bg-[#e0e6e6]/10" },
  { fruit: "grapes", color: "bg-[#f4ebe2] dark:bg-[#f4ebe2]/10" },
  { fruit: "watermelon", color: "bg-[#e6eddb] dark:bg-[#e6eddb]/10" },
  { fruit: "orange", color: "bg-[#fdebdf] dark:bg-[#fdebdf]/10" },
  { fruit: "avocado", color: "bg-[#ecefda] dark:bg-[#ecefda]/10" },
  { fruit: "apple", color: "bg-[#F9E7E4] dark:bg-[#F9E7E4]/10" },
  { fruit: "pear", color: "bg-[#f1f1cf] dark:bg-[#f1f1cf]/10" },
  { fruit: "plum", color: "bg-[#ece5ec] dark:bg-[#ece5ec]/10" },
  { fruit: "banana", color: "bg-[#fdf0dd] dark:bg-[#fdf0dd]/10" },
  { fruit: "strawberry", color: "bg-[#f7e6df] dark:bg-[#f7e6df]/10" },
  { fruit: "lemon", color: "bg-[#feeecd] dark:bg-[#feeecd]/10" },
];

/**
 * Registers the product-search MCP App widget and its companion data tool.
 *
 * Widget UI:  resources/product-search-result/widget.tsx
 *             ↑ This is the React component rendered in the iframe.
 *
 * Tools registered here:
 *   - search-tools       → triggers the widget UI (visual search results carousel)
 *   - get-fruit-details  → data tool called from within the widget via useCallTool()
 */
export function register(server: MCPServer) {
  // MCP App widget tool — calls return widget({ props }) which renders the React component
  server.tool(
    {
      name: "search-tools",
      description:
        "Search for fruits and display the results in a visual widget",
      schema: z.object({
        query: z.string().optional().describe("Search query to filter fruits"),
      }),
      widget: {
        name: "product-search-result", // must match the folder name under resources/
        invoking: "Searching...",
        invoked: "Results loaded",
      },
      _meta: {
        // Preview data shown in MCP UI Studio when no live call has been made yet
        "ui/previewData": {
          query: "tropical",
          results: [
            { fruit: "mango", color: "bg-[#FBF1E1] dark:bg-[#FBF1E1]/10" },
            { fruit: "pineapple", color: "bg-[#f8f0d9] dark:bg-[#f8f0d9]/10" },
            { fruit: "coconut", color: "bg-[#fbedd3] dark:bg-[#fbedd3]/10" },
            { fruit: "banana", color: "bg-[#fdf0dd] dark:bg-[#fdf0dd]/10" },
          ],
        },
      },
    },
    async ({ query }) => {
      const results = fruits.filter(
        (f) => !query || f.fruit.toLowerCase().includes(query.toLowerCase()),
      );
      // Simulate network delay to demonstrate the loading state in the widget
      await new Promise((resolve) => setTimeout(resolve, 2000));
      return widget({
        props: { query: query ?? "", results },
        output: text(
          `Found ${results.length} fruits matching "${query ?? "all"}"`,
        ),
      });
    },
  );

  // Companion data tool — called from within the widget via useCallTool("get-fruit-details")
  server.tool(
    {
      name: "get-fruit-details",
      description: "Get detailed information about a specific fruit",
      schema: z.object({
        fruit: z.string().describe("The fruit name"),
      }),
      outputSchema: z.object({
        fruit: z.string(),
        color: z.string(),
        facts: z.array(z.string()),
      }),
    },
    async ({ fruit }) => {
      const found = fruits.find(
        (f) => f.fruit?.toLowerCase() === fruit?.toLowerCase(),
      );
      return object({
        fruit: found?.fruit ?? fruit,
        color: found?.color ?? "unknown",
        facts: [
          `${fruit} is a delicious fruit`,
          `Color: ${found?.color ?? "unknown"}`,
        ],
      });
    },
  );
}
